const STATUS = { ACTIVE: 'active' } as const;
type Status = (typeof STATUS)[keyof typeof STATUS];
const StatusSchema = z.enum([STATUS.ACTIVE]);

// Good:
model: ModelSchema.default('sonnet')

// Bad:
model: ModelSchema.default('sonnet').optional()

// Problem: .default({}) doesn't propagate inner defaults
settings: SettingsSchema.default({}) // Returns {} not {theme:'system'}

// Solution: Transform explicitly applies defaults
settings: SettingsSchema.optional().transform((s) => ({
  theme: s?.theme ?? 'system',
  locale: s?.locale ?? 'en'
}))

import { FeatureIdSchema, SessionIdSchema } from './ids';

export const SessionSchema = z.object({
  id: SessionIdSchema,
  featureId: FeatureIdSchema,
