app.get('/health', async (c) => {
  let database = 'connected';
  try {
    await db.run(sql`SELECT 1`);
  } catch {
    database = 'disconnected';
    return c.json({
      status: 'unhealthy',
      version: '1.0.0',
      database,
      uptime: process.uptime(),
      timestamp: new Date().toISOString()
    }, 503);
  }
  return c.json({
    status: 'healthy',
    version: '1.0.0',
    database,
    uptime: process.uptime(),
    timestamp: new Date().toISOString()
  });
});

const listSessionsInput = z.object({
  status: SessionStatusSchema.optional(),
  featureId: FeatureIdSchema.optional(),
}).optional();

export const sessionRouter = {
  list: protectedProcedure.input(listSessionsInput).handler(async ({ input }) => {
    if (input?.status) return sessionRepository.findByStatus(input.status);
    if (input?.featureId) return sessionRepository.findByFeature(input.featureId);
    return sessionRepository.findAll();
  }),
  appendOutput: protectedProcedure.input(appendOutputInput).handler(async ({ input }) => {
    return await sessionRepository.appendOutput(input.id, input.text);
  }),
  getDuration: protectedProcedure.input(z.object({ id: SessionIdSchema })).handler(async ({ input }) => {
    const session = await sessionRepository.findById(input.id);
    if (!session) throw new ORPCError('NOT_FOUND', { message: `Session not found` });
    return { duration: sessionRepository.calculateDuration(session) };
  }),
};

const VALID_TRANSITIONS: Record<string, string[]> = {
  [FEATURE_STATUS.BACKLOG]: [FEATURE_STATUS.PENDING, FEATURE_STATUS.FAILED],
  [FEATURE_STATUS.PENDING]: [FEATURE_STATUS.IN_PROGRESS, FEATURE_STATUS.FAILED],
  [FEATURE_STATUS.IN_PROGRESS]: [FEATURE_STATUS.WAITING_APPROVAL, FEATURE_STATUS.FAILED],
  [FEATURE_STATUS.VERIFIED]: [],
};

// In updateStatus handler:
const allowed = VALID_TRANSITIONS[feat.status];
if (!allowed || !allowed.includes(input.status)) {
  throw new ORPCError('BAD_REQUEST', {
    message: `Invalid status transition: ${feat.status} → ${input.status}`,
  });
}
